package ioswhatsapp_test

import (
	"crypto/sha256"
	"encoding/hex"
	"path/filepath"
	"strings"
	"testing"

	"github.com/rbenzing/minutiae/internal/parsers/parsertest"
)

// The fixtures of plan 4I2 (spec 9.1): generated by tools/fixtures/whatsapp_ios_chats.py, committed, pinned by hash. The DDL
// is constructed from memory (tools/fixtures/schemas/whatsapp-ios/CROSSCHECK.md).
const (
	domainConsumer = "AppDomainGroup-group.net.whatsapp.WhatsApp.shared"
	domainBusiness = "AppDomainGroup-group.net.whatsapp.WhatsAppSMB.shared"
	dbName         = "ChatStorage.sqlite"
	appGroup       = "Containers/Shared/AppGroup/5A0B4C3D-0000-4000-8000-00000000A001"
	extractRemote  = "/private/var/mobile/" + appGroup + "/" + dbName
	extractLogical = "ios:HomeDomain/" + appGroup + "/" + dbName
)

var variants = []string{
	"ios-chatstorage", "ios-chatstorage-business", "ios-chatstorage-extract", "ios-chatstorage-renumbered",
	"ios-chatstorage-nomodel", "ios-chatstorage-othermodel", "ios-chatstorage-otherapp", "ios-chatstorage-nooptional",
	"ios-chatstorage-deleted",
}

// placeOf is where a variant sits: a backup variant is bundled with BundleIOSBackup(h, domain, rel) and has an empty
// logical; an extraction variant (an empty domain) with BundleIOS(h, rel, logical), rel being the remote path of the
// database, and no extras (BundleIOS refuses them).
func placeOf(variant string) (domain, rel, logical string) {
	switch variant {
	case "ios-chatstorage-business":
		return domainBusiness, dbName, ""
	case "ios-chatstorage-extract", "ios-chatstorage-otherapp":
		return "", extractRemote, extractLogical
	}
	return domainConsumer, dbName, ""
}

func bundleOf(h *parsertest.Harness, fx parsertest.Fixture, variant string) parsertest.Bundle {
	domain, rel, logical := placeOf(variant)
	if domain == "" {
		return fx.BundleIOS(h, rel, logical)
	}
	return fx.BundleIOSBackup(h, domain, rel)
}

func TestFixturesArePinnedByHash(t *testing.T) {
	seen := map[string]bool{}
	for _, v := range variants {
		fx := parsertest.LoadFixture(t, "testdata", v)
		for role, data := range fx.Files {
			sum := sha256.Sum256(data)
			key := v + "." + role
			seen[key] = true
			if want, ok := fixturePins[key]; !ok || want != hex.EncodeToString(sum[:]) {
				t.Errorf("%s: sha256 %x is not the pinned value %q (regenerate image, oracle and pin together)", key, sum, want)
			}
		}
	}
	for key := range fixturePins {
		if !seen[key] {
			t.Errorf("pin %s has no fixture file", key)
		}
	}
}

func TestEveryCommittedFixtureIsInTheVariantList(t *testing.T) {
	all, err := filepath.Glob("testdata/*.expect.json")
	if err != nil {
		t.Fatal(err)
	}
	var m []string
	for _, p := range all {
		if !strings.HasSuffix(p, ".recover.expect.json") { // the typed recovery oracles come with the claims (plan 4I2 task 6)
			m = append(m, p)
		}
	}
	if len(m) != len(variants) {
		t.Errorf("%d fixtures on disk, %d in the variant list", len(m), len(variants))
	}
	for _, p := range m {
		name := strings.TrimSuffix(filepath.Base(p), ".expect.json")
		known := false
		for _, v := range variants {
			known = known || v == name
		}
		if !known {
			t.Errorf("testdata/%s is not in the variant list", name)
		}
	}
}

// TestFixturesAreBundledWhereTheyAreWritten places every variant with placeOf: the database lands at the logical path
// the globs of the parser will name, and the media files of ios-chatstorage land at <container>/Message/<path>.
func TestFixturesAreBundledWhereTheyAreWritten(t *testing.T) {
	for _, v := range variants {
		fx := parsertest.LoadFixture(t, "testdata", v)
		h := parsertest.NewHarness(t)
		b := bundleOf(h, fx, v)
		domain, rel, logical := placeOf(v)
		want := logical
		if domain != "" {
			want = "ios:" + domain + "/" + rel
		}
		if b.Primary.Logical != want {
			t.Errorf("%s: the database is at %q, want %q", v, b.Primary.Logical, want)
		}
	}
	fx := parsertest.LoadFixture(t, "testdata", "ios-chatstorage")
	b := bundleOf(parsertest.NewHarness(t), fx, "ios-chatstorage")
	for _, p := range []string{"Message/Media/15550000001@s.whatsapp.net/a/b/IMG-0004.jpg", "Message/Media/15550000001@s.whatsapp.net/a/b/STK-0043.webp"} {
		if _, ok := b.ByPath["ios:"+domainConsumer+"/"+p]; !ok {
			t.Errorf("no extra file at %s", p)
		}
	}
	if _, ok := b.ByRole["wal"]; !ok {
		t.Error("ios-chatstorage has no -wal companion in its bundle")
	}
}
